    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"Vault Release — response payload","type":"object","additionalProperties":false,"required":["sealedSecret","secretKind","ttlSeconds"],"properties":{"sealedSecret":{"\$ref":"#/\$defs/SealedEnvelope","description":"Pluggable cipher envelope. Cleartext is a `vault/_shared/0.1/vault-secret#/\$defs/VaultSecret`. Consumers reject envelope kinds they don\'t implement with `vault/release:envelopeUnsupported`."},"secretKind":{"\$ref":"#/\$defs/SecretKind","description":"Discriminator so the consumer can pre-allocate the right type before unsealing."},"ttlSeconds":{"type":"integer","minimum":1,"maximum":600,"description":"Cache TTL the consumer MUST enforce — wipe the cleartext after this many seconds, even if the user has not finished interacting with it."},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"SecretKind":{"title":"SecretKind","type":"string","enum":["password","passkey","oauthTokens","didSelfIssued","didcommPeer","bearerToken","sshKey","custom"],"description":"Discriminator for the secret type stored in the entry. Definitions:\\n- `password` — username + password (+ optional TOTP seed).\\n- `passkey` — WebAuthn discoverable credential (private key + rpId + userHandle).\\n- `oauthTokens` — OAuth 2.0 refresh + access token bundle for a specific provider.\\n- `didSelfIssued` — Self-Issued OpenID Provider v2 (SIOP) credential: the entry points at a DID + signing key already managed by the VTA.\\n- `didcommPeer` — DIDComm peer identity used to authenticate against a DIDComm-speaking relying party.\\n- `bearerToken` — opaque bearer token carried in a maintainer-named header (covers API tokens, long-lived JWTs, personal-access tokens).\\n- `sshKey` — SSH private key + comment.\\n- `custom` — arbitrary structured fields; release-time consumer responsible for interpretation."},"SealedEnvelope":{"title":"SealedEnvelope","description":"Discriminated by `envelope`. Exactly one variant matches per document.","oneOf":[{"\$ref":"#/\$defs/DidcommAuthcryptEnvelope"},{"\$ref":"#/\$defs/HpkeArmoredEnvelope"},{"\$ref":"#/\$defs/TspMessageEnvelope"}]},"TspMessageEnvelope":{"title":"TspMessageEnvelope","description":"Trust Spanning Protocol message (https://trustoverip.github.io/tswg-tsp-specification/). Reserved variant; no OpenVTC component reads or emits this today. Listed in the union so implementations can declare intent to use TSP in discovery and so consumers reject `tspMessage` envelopes explicitly (`envelopeUnsupported`) until they\'re wired up — rather than silently failing in DIDComm parsing.","type":"object","additionalProperties":false,"required":["envelope","message"],"properties":{"envelope":{"const":"tspMessage"},"message":{"type":"string","minLength":1,"description":"Base64url-encoded TSP message bytes. Format reference: https://trustoverip.github.io/tswg-tsp-specification/#message-format"}}},"HpkeArmoredEnvelope":{"title":"HpkeArmoredEnvelope","description":"OpenPGP-style ASCII-armored HPKE bundle — the existing OpenVTC sealed-transfer wire form (X25519-HKDF-SHA256 KEM + ChaCha20-Poly1305 AEAD, framed in armor with Bundle-Id / Digest-Algo headers and a CRC24 checksum). Producer assertion (`didSigned` / `attested` / `pinnedOnly`) is the integrity / authenticity anchor.\\n\\nNo open-source implementation reads this yet outside vta-sdk\'s `sealed_transfer` crate; new code SHOULD prefer the DIDComm variant. Defined here for parity with the existing offline-bundle / cross-VTA workflows that the design plan reserves for M5+.","type":"object","additionalProperties":false,"required":["envelope","armored","recipientKeyId"],"properties":{"envelope":{"const":"hpkeArmored"},"armored":{"type":"string","minLength":1,"description":"ASCII-armored bundle text. Multi-line base64 with framing headers + CRC24."},"recipientKeyId":{"type":"string","minLength":1,"description":"did:key identifier of the X25519 public key the envelope was sealed to. The recipient uses this to select the matching private key."},"producerAssertion":{"type":"string","enum":["didSigned","attested","pinnedOnly"],"default":"didSigned","description":"Producer-assertion mode per the sealed-transfer framework. `didSigned` = Ed25519 signature by issuer; `attested` = TEE attestation quote (e.g. Nitro); `pinnedOnly` = OOB SHA-256 digest only (dev/test, NOT for production)."}}},"DidcommAuthcryptEnvelope":{"title":"DidcommAuthcryptEnvelope","description":"DIDComm v2 authcrypt JWE (ECDH-1PU + A256CBC-HS512, X25519/P-256 key agreement). Sender authentication is the JWE\'s `skid` — the producer\'s DID#keyAgreement. The maintainer\'s keyAgreement key is the recipient. Cleartext is JCS-canonical JSON of the variant\'s payload type.\\n\\nM2A is the only implementation today; this is also the canonical default for new code.","type":"object","additionalProperties":false,"required":["envelope","jwe"],"properties":{"envelope":{"const":"didcommAuthcrypt"},"jwe":{"type":"string","minLength":1,"description":"Compact DIDComm v2 JWE (base64url-encoded, dot-separated). Unpacks via the framework\'s standard DIDComm machinery; cleartext is the payload-specific JSON."}}},"StepUpProof":{"title":"StepUpProof","type":"object","additionalProperties":false,"required":["kind","proof","challengeId"],"properties":{"kind":{"type":"string","enum":["webauthnUv","pushApproval","totp"]},"proof":{"type":"string","description":"Format depends on kind: WebAuthn assertion (base64url), DIDComm approval-response message id, or 6–8-digit TOTP code."},"challengeId":{"type":"string","minLength":1,"description":"Maintainer-issued challenge id the proof responds to."}}},"ConsumerContext":{"title":"ConsumerContext","type":"object","additionalProperties":false,"properties":{"deviceId":{"type":"string","minLength":1,"description":"Device-binding id assigned at registration. The maintainer cross-checks this against the authenticated transport identity."},"lastUserVerificationAt":{"type":"string","format":"date-time","description":"Most recent local user-verification on the consumer device (WebAuthn UV, biometric unlock). The maintainer\'s policy may require this to be within N seconds."},"networkClass":{"type":"string","enum":["unknown","home","corp","public","vpn"],"description":"Producer-supplied network classification. Advisory."}}},"SiteTarget":{"title":"SiteTarget","description":"A single binding target for a vault entry. Tagged union over the discriminator `kind`. A VaultEntry\'s `targets` array MAY mix any number of these.","oneOf":[{"title":"WebOrigin","type":"object","additionalProperties":false,"required":["kind","origin"],"properties":{"kind":{"const":"webOrigin"},"origin":{"type":"string","format":"uri","description":"Web origin per RFC 6454 (scheme + host + optional port), e.g. \\"https://github.com\\". Compared by exact string equality after canonicalisation (lowercase host, default port elided). Consumers wanting subdomain coverage SHOULD add multiple targets, not encode a wildcard."}}},{"title":"Did","type":"object","additionalProperties":false,"required":["kind","did"],"properties":{"kind":{"const":"did"},"did":{"type":"string","minLength":1,"description":"DID identifying the relying party (e.g. did:web:rp.example). The vault maintainer is responsible for any DID resolution required to act on this entry."}}},{"title":"IosApp","type":"object","additionalProperties":false,"required":["kind","bundleId"],"properties":{"kind":{"const":"iosApp"},"bundleId":{"type":"string","minLength":1,"pattern":"^[A-Za-z0-9.-]+\$","description":"iOS bundle identifier in reverse-DNS form (e.g. \\"com.github.stwalkerster.codehub\\"). Compared by exact string equality. Matches when an iOS Companion identifies the requesting app via its bundle id (typically via the OS Credential Manager integration)."},"teamId":{"type":"string","minLength":1,"pattern":"^[A-Z0-9]+\$","description":"Optional Apple Developer Team identifier (10-character alphanumeric). When supplied, the maintainer SHOULD also verify the team id of the requesting app before matching — defense in depth against bundle-id squatting on jailbroken devices."}}},{"title":"AndroidApp","type":"object","additionalProperties":false,"required":["kind","packageName","sha256CertFingerprints"],"properties":{"kind":{"const":"androidApp"},"packageName":{"type":"string","minLength":1,"pattern":"^[A-Za-z][A-Za-z0-9_]*(\\\\.[A-Za-z][A-Za-z0-9_]*)+\$","description":"Android package name in reverse-DNS form (e.g. \\"com.github.android\\")."},"sha256CertFingerprints":{"type":"array","minItems":1,"items":{"type":"string","pattern":"^[0-9A-F]{2}(:[0-9A-F]{2}){31}\$"},"uniqueItems":true,"description":"SHA-256 fingerprints of the app\'s signing certificates, in colon-separated hex (the format `apksigner` and the Play Console emit). At least one fingerprint MUST be present. The maintainer matches when ANY of the provided fingerprints matches the requesting app\'s signature — this supports apps signed by multiple keys (e.g. during certificate rotation via Play App Signing)."}}}]}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
